package kr.workbench;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.zip.*;

/** Dependency-free OOXML export; all cells are strings, never executable formulas. */
final class MetadataExport {
 static void xlsx(Path path,LinkedHashMap<String,List<List<String>>> sheets)throws IOException {
  Path parent=path.toAbsolutePath().getParent(),tmp=Files.createTempFile(parent,"workbench-",".xlsx.tmp");
  try {try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(tmp))){
   StringBuilder types=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>");
   StringBuilder workbook=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>"),rels=new StringBuilder("<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">");int id=0;
   for(var sheet:sheets.entrySet()){id++;types.append("<Override PartName=\"/xl/worksheets/sheet").append(id).append(".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>");workbook.append("<sheet name=\"").append(xml(sheet.getKey())).append("\" sheetId=\"").append(id).append("\" r:id=\"rId").append(id).append("\"/>");rels.append("<Relationship Id=\"rId").append(id).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet").append(id).append(".xml\"/>");
    StringBuilder data=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><sheetData>");int row=0,max=0;for(List<String> cells:sheet.getValue()){row++;data.append("<row r=\"").append(row).append("\">");int col=0;for(String cell:cells){data.append("<c r=\"").append(column(++col)).append(row).append("\" t=\"inlineStr\"><is><t xml:space=\"preserve\">").append(xml(cell==null?"":cell.substring(0,Math.min(cell.length(),32767)))).append("</t></is></c>");}max=Math.max(max,col);data.append("</row>");}data.append("</sheetData>");if(row>0&&max>0)data.append("<autoFilter ref=\"A1:").append(column(max)).append(row).append("\"/>");data.append("</worksheet>");entry(z,"xl/worksheets/sheet"+id+".xml",data.toString());
   }
   entry(z,"[Content_Types].xml",types.append("</Types>").toString());entry(z,"xl/workbook.xml",workbook.append("</sheets></workbook>").toString());entry(z,"xl/_rels/workbook.xml.rels",rels.append("</Relationships>").toString());entry(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
  }Files.move(tmp,path,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(tmp);}
 }
 private static void entry(ZipOutputStream z,String name,String text)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(text.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
 private static String column(int n){String s="";while(n>0){n--;s=(char)('A'+n%26)+s;n/=26;}return s;}
 static String xml(String s){return s.replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]","").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String json(Object o){if(o==null)return "null";if(o instanceof Boolean||o instanceof Number)return o.toString();if(o instanceof Map<?,?> m){List<String> parts=new ArrayList<>();m.forEach((k,v)->parts.add(json(k.toString())+":"+json(v)));return "{"+String.join(",",parts)+"}";}if(o instanceof Collection<?> c)return "["+String.join(",",c.stream().map(MetadataExport::json).toList())+"]";StringBuilder b=new StringBuilder("\"");for(char c:o.toString().toCharArray()){switch(c){case '"'->b.append("\\\"");case '\\'->b.append("\\\\");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");default->{if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}}return b.append('"').toString();}
}
